package com.lumintra.backend.media.domain.service;

import com.lumintra.backend.media.domain.model.MediaPurpose;
import com.lumintra.backend.shared.exception.media.InvalidMediaUrlException;
import lombok.RequiredArgsConstructor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

/**
 * Validates a private media reference submitted to a downstream endpoint (chat message, commission attachment,
 * draft, warranty evidence) and normalizes it to the object key that gets persisted.
 * <p>
 * The reference must point at a file generated by {@code POST /api/media/upload-url} for the same purpose and scope
 * (commission, device or customer), and the file must actually have been uploaded to the private bucket.
 * This stops callers from attaching media that belongs to another commission, device or customer.
 */
@Component
@RequiredArgsConstructor
public class PrivateMediaReferenceValidator {

    private static final Logger log = LoggerFactory.getLogger(PrivateMediaReferenceValidator.class);

    private final MediaReferenceParser mediaReferenceParser;
    private final MediaKeyGenerator mediaKeyGenerator;
    private final StorageSignedUrlService storageSignedUrlService;

    /**
     * @param reference the object key returned by the upload-url endpoint (a legacy media URL is also accepted)
     * @param purpose   a private purpose
     * @param scopeId   commissionId for COMMISSION_CHAT / COMMISSION_DRAFT, deviceId for WARRANTY_EVIDENCE,
     *                  customer account ID for COMMISSION_REFERENCE
     * @return the normalized object key to persist
     */
    public String requireOwnedObjectKey(String reference, MediaPurpose purpose, Long scopeId) {
        if (purpose == null || !purpose.isPrivate()) {
            throw new IllegalArgumentException("Purpose must be a private media purpose: " + purpose);
        }
        if (scopeId == null || scopeId <= 0) {
            throw new IllegalArgumentException("A positive scope ID is required to validate " + purpose + " media.");
        }

        String objectKey = mediaReferenceParser.extractObjectKey(reference)
                .orElseThrow(() -> {
                    log.warn("Rejected invalid private media reference [purpose={}] [scopeId={}]", purpose, scopeId);
                    return new InvalidMediaUrlException(
                            "Submitted media reference is not a valid uploaded media object key.");
                });

        String scope = String.valueOf(scopeId);
        String expectedFolder = mediaKeyGenerator.folderFor(purpose, scope, scopeId);
        if (!mediaKeyGenerator.isGeneratedKeyInFolder(objectKey, expectedFolder)) {
            log.warn("Rejected private media outside expected scope [purpose={}] [scopeId={}] [objectKey={}] [expectedFolder={}]",
                    purpose, scopeId, objectKey, expectedFolder);
            throw new InvalidMediaUrlException(
                    "Submitted media does not belong to this " + scopeLabel(purpose) + " or was not issued for " + purpose + ".");
        }

        if (!storageSignedUrlService.privateObjectExists(objectKey)) {
            log.warn("Rejected private media reference whose object is missing from bucket [purpose={}] [scopeId={}] [objectKey={}]",
                    purpose, scopeId, objectKey);
            throw new InvalidMediaUrlException("Submitted media has not been uploaded yet.");
        }
        return objectKey;
    }

    private static String scopeLabel(MediaPurpose purpose) {
        return switch (purpose) {
            case COMMISSION_CHAT, COMMISSION_DRAFT -> "commission";
            case WARRANTY_EVIDENCE -> "device";
            case COMMISSION_REFERENCE -> "customer";
            default -> "scope";
        };
    }
}
